SELECT backup_id, file_name, file_path, file_size_bytes, compressed_size_bytes, checksum_sha256, database_name, created_by, status, verification_status, restore_test_status, created_at, completed_at, duration_seconds FROM backups WHERE 1=1 AND (%(date_from)s IS NULL OR created_at >= %(date_from)s) AND (%(date_to)s IS NULL OR created_at <= %(date_to)s) ORDER BY created_at DESC LIMIT %(limit)s OFFSET %(offset)s
